// valueOptions are the encoding options attached to one entry of a table.
type valueOptions struct {
	multiline bool
	inline    bool
	omitempty bool
	omitzero  bool
	commented bool
	comment   string
}

// entry is a deferred key-value of a table being encoded. Entries collected
// from a generic map[string]interface{} carry the value as anyValue (with a
// zero reflect.Value): the whole generic tree then encodes through concrete
// type switches, without reflection.
type entry struct {
	key      string
	value    reflect.Value
	anyValue interface{}
	// options points into the encoder plan (or at zeroValueOptions for map
	// entries): entries are copied around, and the options are the widest
	// part of them.
	options *valueOptions
	class   entryClass
	// pf points to the plan field the entry came from, carrying its
	// statically-known facts; nil for map entries.
	pf *encPlanField
}

// zeroValueOptions is the shared options of entries that have no tags.
var zeroValueOptions valueOptions

// entryClass tells how an entry of a table is emitted. It is computed once
// per entry: classifying requires resolving the value's type (and for arrays,
// the type of every element), which would otherwise be repeated by each of
// the encoding passes.
type entryClass uint8

const (
	classKeyValue entryClass = iota
	classTable
	classArrayTable
)

// classify computes the entryClass of an entry.
func (e *encoderState) classify(ent *entry) entryClass {
	if e.tablesInline || ent.options.inline {
		return classKeyValue
	}
	if ent.pf != nil && ent.pf.classKnown {
		return ent.pf.staticClass
	}
	if ent.anyValue != nil {
		switch v := ent.anyValue.(type) {
		case map[string]interface{}:
			return classTable
		case []interface{}:
			if len(v) == 0 {
				return classKeyValue
			}
			for _, elem := range v {
				if _, ok := elem.(map[string]interface{}); !ok {
					// Mixed or exotic elements: decide like the reflection
					// path would (resolving pointers and interfaces).
					if e.isArrayOfTables(reflect.ValueOf(ent.anyValue)) {
						return classArrayTable
					}
					return classKeyValue
				}
			}
			return classArrayTable
		case time.Time, LocalDate, LocalTime, LocalDateTime:
			return classKeyValue
		default:
			// Not a generic container: classify through reflection.
			v2 := reflect.ValueOf(ent.anyValue)
			if e.isArrayOfTables(v2) {
				return classArrayTable
			}
			if e.isTableLike(v2) {
				return classTable
			}
			return classKeyValue
		}
	}
	if e.isArrayOfTables(ent.value) {
		return classArrayTable
	}
	if e.isTableLike(ent.value) {
		return classTable
	}
	return classKeyValue
}

func (e *encoderState) encodeRoot(v interface{}) error {
	if v == nil {
		return errors.New("toml: cannot encode a nil interface")
	}

	if m, ok := v.(map[string]interface{}); ok {
		// Generic documents skip reflection entirely: their entries are
		// collected natively and every value encodes by type switch.
		entries := e.getEntries()
		for key, value := range m {
			if value == nil {
				// nil interface values are skipped
				continue
			}
			entries = append(entries, entry{key: key, anyValue: value, options: &zeroValueOptions})
		}
		if len(entries) > 1 {
			slices.SortFunc(entries, func(a, b entry) int {
				return strings.Compare(a.key, b.key)
			})
		}
		return e.encodeEntries(entries, false, 0)
	}

	rv := reflect.ValueOf(v)
	rv, ok := resolve(rv)
	if !ok {
		return errors.New("toml: cannot encode a nil pointer")
	}

	switch rv.Kind() {
	case reflect.Map, reflect.Struct:
		if isValueKind(rv) {
			return fmt.Errorf("toml: cannot encode a %s as a document root", rv.Type())
		}
		return e.encodeTable(rv, false, 0)
	default:
		return fmt.Errorf("toml: cannot encode a %s as a document root", rv.Type())
	}
}

// resolve unwraps pointers and interfaces until a concrete value is found.
// Returns false if it resolves to nil.
func resolve(v reflect.Value) (reflect.Value, bool) {
	for {
		switch v.Kind() {
		case reflect.Ptr:
			if v.IsNil() {
				return v, false
			}
			v = v.Elem()
		case reflect.Interface:
			if v.IsNil() {
				return v, false
			}
			v = v.Elem()
		default:
			return v, true
		}
	}
}

// typeEncProps caches the per-type facts used on every value encode.
type typeEncProps struct {
	// 0: not a TextMarshaler, 1: the type implements it, 2: its pointer does
	text uint8
	// encoded as a TOML value (as opposed to a table)
	isValue bool
}

var typeEncPropsCache sync.Map // reflect.Type -> typeEncProps

// builtinEncProps resolves the encoding properties of the handful of builtin
// types that make up generic documents (map[string]interface{} trees), none
// of which can implement TextMarshaler, with a kind dispatch and one pointer
// comparison instead of a cache lookup.
func builtinEncProps(t reflect.Type) (typeEncProps, bool) {
	switch t.Kind() {
	case reflect.String:
		if t == stringType {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Bool:
		if t == boolType {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Int:
		if t == intType {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Int64:
		if t == int64Type {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Float64:
		if t == float64Type {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Slice:
		if t == sliceInterfaceType {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Map:
		if t == mapStringInterfaceType {
			return typeEncProps{isValue: false}, true
		}
	}
	return typeEncProps{}, false
}

func encPropsForType(t reflect.Type) typeEncProps {
	if p, ok := builtinEncProps(t); ok {
		return p
	}
	if p, ok := typeEncPropsCache.Load(t); ok {
		return p.(typeEncProps)
	}
	var p typeEncProps
	switch {
	case t.Implements(textMarshalerType):
		p.text = 1
	case reflect.PtrTo(t).Implements(textMarshalerType):
		p.text = 2
	}
	switch t {
	case timeType, localDateType, localTimeType, localDateTimeType:
		p.isValue = true
	default:
		if p.text != 0 {
			p.isValue = true
		} else {
			switch t.Kind() {
			case reflect.Map, reflect.Struct:
				p.isValue = false
			default:
				p.isValue = true
			}
		}
	}
	typeEncPropsCache.Store(t, p)
	return p
}

// isValueKind returns true when the resolved value is encoded as a TOML
// value (as opposed to a table).
func isValueKind(v reflect.Value) bool {
	return encPropsForType(v.Type()).isValue
}

// isTableLike returns true when the value should be encoded as a table (or
// an array of tables for slices).
func (e *encoderState) isTableLike(v reflect.Value) bool {
	v, ok := resolve(v)
	if !ok {
		// Unresolvable values (interface-held nil pointers) are encoded as
		// the zero value of their element type by the value path.
		return false
	}
	return !e.propsFor(v.Type()).isValue
}

// isArrayOfTables returns true when the value is a non-empty slice or array
// containing only table-like values.
func (e *encoderState) isArrayOfTables(v reflect.Value) bool {
	v, ok := resolve(v)
	if !ok {
		return false
	}
	if v.Kind() != reflect.Slice && v.Kind() != reflect.Array {
		return false
	}
	if v.Len() == 0 {
		return false
	}
	for i := 0; i < v.Len(); i++ {
		elem, ok := resolve(v.Index(i))
		if !ok || e.propsFor(elem.Type()).isValue {
			return false
		}
	}
	return true
}

